df['cyl_num'] = df['気筒数'].fillna('').str.extract(r'(\d+)', expand=False).astype(float)
cond_map = {'new':5,'like new':4,'excellent':3,'good':2,'fair':1,'salvage':0}
df['cond_ord'] = df['状態'].fillna('').str.lower().str.strip().map(cond_map).astype(float)
title_map = {'clean':3,'lien':2,'rebuilt':1,'salvage':0,'parts only':0,'missing':1}
df['title_ord'] = df['名義状態'].fillna('').str.lower().str.strip().map(title_map).astype(float)
